<!doctype html><html lang="{{ app()->getLocale() }}"><head><meta charset="utf-8"><style>@page{margin:8mm 5mm}body{width:302px;margin:auto;font-family:DejaVu Sans,sans-serif;font-size:11px}.center{text-align:center}.line{border-top:1px dashed #555;margin:10px 0}.row{margin:6px 0}.amount{font-size:17px;font-weight:bold;text-align:center;margin:12px 0}.small{font-size:9px;color:#444}</style></head><body><div class="center"><strong style="font-size:16px">GUT Center</strong><br><span class="small">{{ __('Registration fee receipt / invoice') }}</span></div><div class="line"></div><div class="row"><strong>{{ __('Date') }} :</strong> {{ $invoice->updated_at?->format('d/m/Y H:i') }}</div><div class="row"><strong>{{ __('Student') }} :</strong> {{ $student->first_name }} {{ $student->last_name }}</div><div class="row"><strong>{{ __('Student number') }} :</strong> {{ $student->student_number }}</div><div class="row"><strong>{{ __('Class') }} :</strong> {{ $schoolClass->name }}</div><div class="line"></div><div class="amount">{{ number_format((float)$invoice->amount_paid,0,',',' ') }} Ar</div><div class="center"><strong>{{ (float)$invoice->amount_paid > 0 ? __('Registration fee collected') : __('Registration fee due') }}</strong><br><span class="small">{{ __('Total amount') }} : {{ number_format((float)$invoice->amount_due,0,',',' ') }} Ar</span><br><span class="small">{{ __('Remaining') }} : {{ number_format(max(0,(float)$invoice->amount_due-(float)$invoice->amount_paid),0,',',' ') }} Ar</span></div><div class="line"></div><div class="center small">{{ __('Thank you.') }}</div></body></html>
